use zen_word::*;
use zen_word::layout::{FontLineHeight,FontLineHeightProvider,FontLineHeightPolicy,ParsedFontLineHeight};
struct Known;
impl FontLineHeightProvider for Known {fn lookup(&self,_:&RunProps)->Option<FontLineHeight>{Some(FontLineHeight::new(2048,2355,"controlled".into()).unwrap())}}
struct Missing;
impl FontLineHeightProvider for Missing {fn lookup(&self,_:&RunProps)->Option<FontLineHeight>{None}}
fn p()->Paragraph{let mut p=Paragraph::text("X");p.runs[0].props.size_half_points=Some(24);p.props.line_spacing=Some(LineSpacing::Auto(480));p}
fn doc()->Document{let mut d=Document::default();d.section=SectionProps {page_width_twips:4000,page_height_twips:1100,margin_top_twips:100,margin_bottom_twips:100,margin_left_twips:200,margin_right_twips:200,..Default::default()};d.styles.default_run.size_half_points=Some(24);d}
#[test]fn automatic_fit_and_full_advance_are_distinct(){let p=p();let (l,_)=LineServices::format_paragraph_with_metrics(&p,3000,&Known);assert_eq!((l[0].fit_height_twips,l[0].height_twips),(276,552));assert!(l[0].ascent_twips<=l[0].fit_height_twips);}
#[test]fn fixed_minimum_missing_and_default_keep_full_footprint(){let mut p=p();for s in [LineSpacing::Exact(552),LineSpacing::AtLeast(552)]{p.props.line_spacing=Some(s);let (l,_)=LineServices::format_paragraph_with_metrics(&p,3000,&Known);assert_eq!((l[0].fit_height_twips,l[0].height_twips),(552,552));}p.props.line_spacing=Some(LineSpacing::Auto(480));let (l,_)=LineServices::format_paragraph_with_metrics(&p,3000,&Missing);assert_eq!((l[0].fit_height_twips,l[0].height_twips),(576,576));let l=LineServices::format_paragraph(&p,3000);assert_eq!(l[0].fit_height_twips,l[0].height_twips);}
#[test]fn empty_line_and_subsingle_fit_bounded(){let mut p=p();p.runs[0].contents.clear();let (l,_)=LineServices::format_paragraph_with_metrics(&p,3000,&Known);assert_eq!((l[0].fit_height_twips,l[0].height_twips),(276,552));p.props.line_spacing=Some(LineSpacing::Auto(120));let (l,_)=LineServices::format_paragraph_with_metrics(&p,3000,&Known);assert_eq!((l[0].fit_height_twips,l[0].height_twips),(138,138));}
#[test]fn keep_terminal_uses_fit_and_cursor_keeps_advance(){let mut d=doc();let mut f=Paragraph::text("F");f.props.line_spacing=Some(LineSpacing::Exact(300));let mut h=Paragraph::text("H");h.props.line_spacing=Some(LineSpacing::Exact(300));h.props.keep_next=true;let mut next=Paragraph::text("NEXT");next.props.page_break_before=true;d.blocks=vec![Block::Paragraph(f),Block::Paragraph(h),Block::Paragraph(p()),Block::Paragraph(next)];let original=d.clone();let (l,_)=PageTableServices::layout_document_with_metrics_checked(&d,&Known).unwrap();assert_eq!(l.total_pages,2);assert_eq!(l.pages[0].placed_lines.len(),3);let (_,y,line)=&l.pages[0].placed_lines[2];assert_eq!(*y,700);assert!(*y+line.fit_height_twips as i32<=1000);assert!(*y+line.height_twips as i32>1000);assert_eq!(d,original);}
#[test]fn next_line_respects_advance_and_still_rejects_unfit_content(){let mut d=doc();let mut f=Paragraph::text("F");f.props.line_spacing=Some(LineSpacing::Exact(600));d.blocks=vec![Block::Paragraph(f),Block::Paragraph(p()),Block::paragraph("Next")];let (l,_)=PageTableServices::layout_document_with_metrics_checked(&d,&Known).unwrap();assert_eq!(l.total_pages,2);assert_eq!(l.pages[0].placed_lines.len(),2);assert_eq!(l.pages[1].placed_lines.len(),1);let Block::Paragraph(q)=&mut d.blocks[1] else{unreachable!()};q.props.line_spacing=Some(LineSpacing::Exact(1000));assert!(PageTableServices::layout_document_with_metrics_checked(&d,&Known).is_err());}
#[test]fn extreme_advance_cannot_wrap_signed_cursor(){let mut d=doc();let mut q=p();q.props.line_spacing=Some(LineSpacing::Auto(u32::MAX));d.blocks.push(Block::Paragraph(q));let original=d.clone();assert!(PageTableServices::layout_document_with_metrics_checked(&d,&Known).is_err());assert_eq!(d,original);}

#[test]
#[ignore="Requires explicit local font, frozen native expectations and output path"]
fn frozen_page_bottom_replay(){
    let font=std::fs::read(std::env::var("ZEN_FIT_FONT").unwrap()).unwrap();let provider=ParsedFontLineHeight::from_bytes(&font,0,"Arial",FontLineHeightPolicy::Hhea,&std::env::var("ZEN_FIT_FONT_ID").unwrap()).unwrap();let input=std::fs::read_to_string(std::env::var("ZEN_FIT_EXPECTATIONS").unwrap()).unwrap();let mut output=String::from("case\tpages\ttarget_page\tnext_page\tfit\tadvance\n");let mut count=0;
    for row in input.lines(){let c:Vec<_>=row.split('\t').collect();assert_eq!(c.len(),5);let bytes=std::fs::read(c[1]).unwrap();let d=read_docx(&bytes).unwrap().document;let original=d.clone();let (l,_)=PageTableServices::layout_document_with_metrics_checked(&d,&provider).unwrap();let flat:Vec<_>=l.pages.iter().flat_map(|p|p.placed_lines.iter().map(move |(_,y,l)|(p.page_number,*y,l))).collect();assert_eq!(flat.len(),3);assert_eq!(l.total_pages,c[2].parse::<usize>().unwrap(),"{}",c[0]);assert_eq!(flat[1].0,c[3].parse::<usize>().unwrap(),"{}",c[0]);assert_eq!(flat[2].0,c[4].parse::<usize>().unwrap(),"{}",c[0]);
        for p in &l.pages{for (_,y,line) in &p.placed_lines{assert!(*y>=p.margin_top_twips);assert!(i64::from(*y)+i64::from(line.fit_height_twips)<=i64::from(p.height_twips-p.margin_bottom_twips));}}
        assert_eq!(d,original);assert_eq!(write_docx(&d).unwrap(),bytes);output.push_str(&format!("{}\t{}\t{}\t{}\t{}\t{}\n",c[0],l.total_pages,flat[1].0,flat[2].0,flat[1].2.fit_height_twips,flat[1].2.height_twips));count+=1;
    }assert_eq!(count,30);std::fs::write(std::env::var("ZEN_FIT_OUTPUT").unwrap(),output).unwrap();
}
